 "content": "def transform(grid):
    # Separators are the full rows/columns of color 5; each tile contains
    # background 2 with zero markers. Highlight the tile with two markers.
    sep = 5
    row_bounds = []
    start = 0
    for r, row in enumerate(grid):
        if all(v == sep for v in row):
            if start < r:
                row_bounds.append((start, r))
            start = r + 1
    if start < len(grid):
        row_bounds.append((start, len(grid)))

    width = len(grid[0])
    col_seps = [c for c in range(width) if all(grid[r][c] == sep for r in range(len(grid)))]
    col_bounds = []
    start = 0
    for c in col_seps:
        if start < c:
            col_bounds.append((start, c))
        start = c + 1
    if start < width:
        col_bounds.append((start, width))

    out = []
    for r0, r1 in row_bounds:
        out_row = []
        for c0, c1 in col_bounds:
            count = sum(grid[r][c] == 0 for r in range(r0, r1) for c in range(c0, c1))
            out_row.append(1 if count == 2 else 2)
        out.append(out_row)
    return out
